import { extractUserId } from '@twurple/common';
/** @internal */
export function getAllPowerUpsQuery(broadcaster) {
    return {
        broadcaster_id: extractUserId(broadcaster),
    };
}
/** @internal */
export function getPowerUpsQuery(broadcaster, rewardIds) {
    return {
        broadcaster_id: extractUserId(broadcaster),
        id: rewardIds,
    };
}
/** @internal */
export function getPowerUpQuery(broadcaster, rewardId) {
    return {
        broadcaster_id: extractUserId(broadcaster),
        id: rewardId,
    };
}
